import { motion } from 'framer-motion';
import { useMemo, useState } from 'react';
import { fmt, mkEvent, seedEvents, timeStr, type EventRow, type Level } from './data';
import { useInterval } from './kit';
import { cardMotion } from './motionPresets';

export type Filter = 'all' | Level;
type SortKey = keyof Pick<EventRow, 'ts' | 'svc' | 'lvl' | 'msg' | 'dur' | 'trace'>;
const COLS: [SortKey, string][] = [['ts', 'Time'], ['svc', 'Service'], ['lvl', 'Level'], ['msg', 'Message'], ['dur', 'Duration'], ['trace', 'Trace']];
const LVL_ORDER: Record<Level, number> = { error: 0, warn: 1, info: 2 };
const PER = 8;

/** Streaming event table: level filters, search, sortable columns, pagination. */
export function EventsTable({ live, filter, onFilter, index }: { live: boolean; filter: Filter; onFilter: (f: Filter) => void; index: number }) {
  const [rows, setRows] = useState<EventRow[]>(seedEvents);
  const [q, setQ] = useState('');
  const [sort, setSort] = useState<{ key: SortKey; dir: 'asc' | 'desc' }>({ key: 'ts', dir: 'desc' });
  const [page, setPage] = useState(1);
  const [newId, setNewId] = useState<number | null>(null);
  const [anim, setAnim] = useState(0); // bumps on every filter/sort/page change so rows stagger in again

  useInterval(() => {
    const e = mkEvent(Date.now());
    setRows((r) => [e, ...r].slice(0, 140));
    setNewId(e.id);
  }, live ? 3000 : null);

  const view = useMemo(() => {
    const s = sort.dir === 'asc' ? 1 : -1, k = sort.key, ql = q.trim().toLowerCase();
    return rows
      .filter((e) => (filter === 'all' || e.lvl === filter) && (!ql || `${e.svc} ${e.msg} ${e.trace}`.toLowerCase().includes(ql)))
      .sort((a, b) => { const A = k === 'lvl' ? LVL_ORDER[a.lvl] : a[k], B = k === 'lvl' ? LVL_ORDER[b.lvl] : b[k]; return (A > B ? 1 : A < B ? -1 : 0) * s; });
  }, [rows, filter, q, sort]);
  const pages = Math.max(1, Math.ceil(view.length / PER));
  const pg = Math.min(page, pages);
  const slice = view.slice((pg - 1) * PER, pg * PER);
  const counts = { all: rows.length, error: 0, warn: 0, info: 0 } as Record<Filter, number>;
  rows.forEach((e) => counts[e.lvl]++);
  const nums: (number | '…')[] = [];
  for (let p = 1; p <= pages; p++) { if (p === 1 || p === pages || Math.abs(p - pg) <= 1) nums.push(p); else if (nums[nums.length - 1] !== '…') nums.push('…'); }
  const go = (p: number) => { setPage(p); setAnim((a) => a + 1); };
  const sortBy = (k: SortKey) => { setSort((s) => ({ key: k, dir: s.key === k ? (s.dir === 'asc' ? 'desc' : 'asc') : k === 'ts' || k === 'dur' ? 'desc' : 'asc' })); setAnim((a) => a + 1); };
  const last = rows[0];

  return (
    <motion.article className="card ev-card" {...cardMotion(index)}>
      <div className="card-h"><h2>Events</h2><span className="sub">streaming · last {timeStr(last.ts)}</span></div>
      <div className="ev-tools">
        <div className="filters" role="group" aria-label="Filter by level">
          {(['all', 'error', 'warn', 'info'] as Filter[]).map((f) => (
            <button key={f} aria-pressed={filter === f} onClick={() => { onFilter(f); go(1); }}>
              {f === 'all' ? 'All' : f === 'error' ? 'Errors' : f === 'warn' ? 'Warnings' : 'Info'}<span className="n">{counts[f]}</span>
            </button>
          ))}
        </div>
        <label className="ev-search">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></svg>
          <span className="sr">Filter events</span>
          <input value={q} onChange={(e) => { setQ(e.target.value); go(1); }} placeholder="Filter by service or message" autoComplete="off" />
        </label>
      </div>
      <div className="tbl-wrap">
        <table aria-label="Events">
          <thead><tr>
            {COLS.map(([k, label]) => (
              <th key={k} aria-sort={sort.key === k ? (sort.dir === 'asc' ? 'ascending' : 'descending') : 'none'}>
                <button onClick={() => sortBy(k)}>{label}<svg viewBox="0 0 10 10" aria-hidden="true"><path d="M1 3l4 4 4-4" fill="none" stroke="currentColor" strokeWidth="1.6" /></svg></button>
              </th>
            ))}
          </tr></thead>
          <tbody key={anim}>
            {slice.length ? slice.map((e, i) => (
              <tr key={e.id} className={e.id === newId && pg === 1 && sort.key === 'ts' && sort.dir === 'desc' ? 'new' : anim ? 'enter' : 'enter'} style={{ ['--r' as string]: i }}>
                <td className="mono">{timeStr(e.ts)}</td><td>{e.svc}</td><td><span className={`lv ${e.lvl}`}>{e.lvl}</span></td>
                <td className="msg" title={e.msg}>{e.msg}</td><td className="mono">{fmt(e.dur)} ms</td><td className="mono">{e.trace}</td>
              </tr>
            )) : (
              <tr><td colSpan={6} className="empty">No events match “{q || filter}”. Try another filter or clear the search.</td></tr>
            )}
          </tbody>
        </table>
      </div>
      <div className="pager">
        <span className="num">{view.length ? (pg - 1) * PER + 1 : 0}–{Math.min(view.length, pg * PER)} of {view.length}</span>
        <div className="pages">
          <button aria-label="Previous page" disabled={pg === 1} onClick={() => go(pg - 1)}>‹</button>
          {nums.map((p, i) => p === '…' ? <span key={'e' + i} aria-hidden="true">…</span> :
            <button key={p} aria-label={`Page ${p}`} aria-current={p === pg ? 'page' : undefined} onClick={() => go(p)}>{p}</button>)}
          <button aria-label="Next page" disabled={pg === pages} onClick={() => go(pg + 1)}>›</button>
        </div>
      </div>
    </motion.article>
  );
}

import { motion } from 'framer-motion';
import { useEffect, useState } from 'react';
import { KPIS, R, RANGES, type KpiKey, type RangeKey } from './data';
import { CountUp, Spark, useInterval } from './kit';
import { cardMotion } from './motionPresets';

type Series = Record<KpiKey, { val: number; hist: number[] }>;
function seed(): Series {
  const s = {} as Series;
  KPIS.forEach((k) => { s[k.key] = { val: k.base, hist: Array.from({ length: 24 }, () => k.base + (R() - 0.5) * k.jitter * 2) }; });
  return s;
}
const target = (key: KpiKey, base: number, f: number) => (key === 'apdex' ? Math.min(0.99, base * (2 - f) * 0.5 + base * 0.5) : key === 'rps' ? base * (2 - f) : base * f);

export function Kpis({ range, live }: { range: RangeKey; live: boolean }) {
  const [s, setS] = useState<Series>(seed);
  const [first, setFirst] = useState(true);
  useEffect(() => {
    const f = RANGES[range].k;
    setS((prev) => {
      const next = { ...prev };
      KPIS.forEach((k) => {
        const p = prev[k.key], v = target(k.key, k.base, f), last = p.hist[p.hist.length - 1];
        next[k.key] = { val: v, hist: p.hist.map((x) => x * (v / last)) };
      });
      return next;
    });
    const t = setTimeout(() => setFirst(false), 1500);
    return () => clearTimeout(t);
  }, [range]);
  useInterval(() => {
    setS((prev) => {
      const next = { ...prev };
      KPIS.forEach((k) => {
        const p = prev[k.key], nv = Math.max(0, p.val + (R() - 0.5) * k.jitter);
        next[k.key] = { val: p.val, hist: [...p.hist.slice(1), nv] };
      });
      return next;
    });
  }, live ? 1000 : null);
  return (
    <>
      {KPIS.map((k, i) => {
        const p = s[k.key];
        return (
          <motion.article key={k.key} className="card kpi" {...cardMotion(i)}>
            <div className="lbl">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d={k.icon} /></svg>
              {k.label}
            </div>
            <div className="val">
              <CountUp value={p.hist[p.hist.length - 1]} decimals={k.d} duration={first ? 1.4 : 0.6} />
              {k.unit && <span>{k.unit}</span>}
            </div>
            <div className="foot">
              <span className={`delta ${k.good ? 'up' : 'down'}`}>{k.delta}<span className="vs">vs last week</span></span>
              <Spark data={p.hist} color={k.color} />
            </div>
          </motion.article>
        );
      })}
    </>
  );
}

import { animate, motion, useReducedMotion } from 'framer-motion';
import { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState } from 'react';
import { C, R, RANGES, genLatency, type Latency, type RangeKey } from './data';
import { TipRow, useInterval, useTip } from './kit';
import { cardMotion } from './motionPresets';

export type LatencyHandle = { hover: (i: number | null) => void; points: () => number };

/** Streaming p50 / p95 / p99 chart with a crosshair. Morphs when the range changes. */
export const LatencyChart = forwardRef<LatencyHandle, { range: RangeKey; live: boolean; index: number }>(function LatencyChart({ range, live, index }, ref) {
  const box = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ w: 360, h: 250 });
  const [S, setS] = useState<Latency>(() => genLatency(range));
  const [hover, setHover] = useState<number | null>(null);
  const reduce = useReducedMotion();
  const tip = useTip();
  const first = useRef(true);
  const sRef = useRef(S); sRef.current = S;

  useLayoutEffect(() => {
    const el = box.current; if (!el) return;
    const ro = new ResizeObserver(() => setSize({ w: el.clientWidth || 360, h: el.clientHeight || 250 }));
    ro.observe(el); return () => ro.disconnect();
  }, []);

  // morph to the new range
  useEffect(() => {
    if (first.current) { first.current = false; return; }
    const next = genLatency(range), cur = sRef.current;
    if (reduce || cur.p50.length !== next.p50.length) { setS(next); return; }
    const from = { p50: cur.p50.slice(), p95: cur.p95.slice(), p99: cur.p99.slice() };
    const c = animate(0, 1, { duration: 0.6, ease: [0.16, 1, 0.3, 1], onUpdate: (p) => setS({
      p50: next.p50.map((v, i) => from.p50[i] + (v - from.p50[i]) * p),
      p95: next.p95.map((v, i) => from.p95[i] + (v - from.p95[i]) * p),
      p99: next.p99.map((v, i) => from.p99[i] + (v - from.p99[i]) * p),
    }) });
    return () => c.stop();
  }, [range, reduce]);

  useInterval(() => setS((cur) => {
    const f = RANGES[range].k, last = cur.p50[cur.p50.length - 1];
    const b = Math.max(52 * f, Math.min(92 * f, last + (R() - 0.5) * 10));
    return { p50: [...cur.p50.slice(1), b], p95: [...cur.p95.slice(1), b * 2.4 + R() * 16], p99: [...cur.p99.slice(1), b * 3.5 + R() * 34] };
  }), live ? 1000 : null);

  const { w: W, h: H } = size, pl = 34, pr = 6, pt = 8, pb = 22;
  const mx = Math.ceil(Math.max(...S.p99) / 100) * 100, n = S.p50.length;
  const X = (i: number) => pl + (i / (n - 1)) * (W - pl - pr), Y = (v: number) => pt + (1 - v / mx) * (H - pt - pb);
  const line = (a: number[]) => a.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ' ' + Y(v).toFixed(1)).join('');
  const area = (a: number[]) => line(a) + `L${X(n - 1)} ${H - pb}L${X(0)} ${H - pb}Z`;
  const L = RANGES[range].labels;

  // tooltip follows the hovered index (also while new points stream in)
  useEffect(() => {
    if (hover == null) return;
    const el = box.current; if (!el) return;
    const r = el.getBoundingClientRect(), i = Math.min(hover, n - 1), ago = n - 1 - i;
    tip.show(<>
      <b>{ago ? `${ago} ${RANGES[range].u} ago` : 'now'}</b>
      <TipRow k="p50" v={Math.round(S.p50[i]) + ' ms'} /><TipRow k="p95" v={Math.round(S.p95[i]) + ' ms'} /><TipRow k="p99" v={Math.round(S.p99[i]) + ' ms'} />
    </>, r.left + X(i) * (r.width / W), r.top + Y(S.p95[i]) * (r.height / H));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hover, S]);

  const setHoverIdx = (i: number | null) => { setHover(i); if (i == null) tip.hide(); };
  useImperativeHandle(ref, () => ({ hover: setHoverIdx, points: () => n }), [n]);
  const onMove = (e: React.PointerEvent) => {
    const r = e.currentTarget.getBoundingClientRect(), x = (e.clientX - r.left) * (W / r.width);
    setHoverIdx(Math.max(0, Math.min(n - 1, Math.round(((x - pl) / (W - pl - pr)) * (n - 1)))));
  };
  const hi = hover == null ? null : Math.min(hover, n - 1);

  return (
    <motion.article className="card lat-card" {...cardMotion(index)}>
      <div className="card-h"><h2>Latency</h2>
        <div className="r legend"><span><i style={{ background: C.cyan }} />p50</span><span><i style={{ background: C.violet }} />p95</span><span><i style={{ background: C.red }} />p99</span></div>
      </div>
      <div className={`lat${hi != null ? ' hover' : ''}`} ref={box} onPointerMove={onMove} onPointerLeave={() => setHoverIdx(null)}>
        <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Latency over time: p50, p95 and p99">
          <defs>
            <linearGradient id="la95" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={C.violet} stopOpacity=".35" /><stop offset="1" stopColor={C.violet} stopOpacity="0" /></linearGradient>
            <linearGradient id="la50" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={C.cyan} stopOpacity=".22" /><stop offset="1" stopColor={C.cyan} stopOpacity="0" /></linearGradient>
            <clipPath id="latClip">
              <motion.rect x={pl} y={0} height={H} initial={{ width: reduce ? W - pl : 0 }} animate={{ width: W - pl }} transition={{ delay: 0.4, duration: 1.4, ease: [0.16, 1, 0.3, 1] }} />
            </clipPath>
          </defs>
          {[0, 1, 2, 3, 4].map((k) => { const v = (mx * k) / 4, y = Y(v); return (
            <g key={k}><line className="gl" x1={pl} x2={W - pr} y1={y} y2={y} /><text className="ax" x={pl - 6} y={y + 3} textAnchor="end">{Math.round(v)}</text></g>); })}
          {[0, 0.5, 1].map((p, i) => <text key={p} className="ax" x={pl + p * (W - pl - pr)} y={H - 6} textAnchor={i === 0 ? 'start' : i === 2 ? 'end' : 'middle'}>{L[i]}</text>)}
          <g clipPath="url(#latClip)">
            <path d={area(S.p95)} fill="url(#la95)" /><path d={area(S.p50)} fill="url(#la50)" />
            <path d={line(S.p99)} fill="none" stroke={C.red} strokeWidth="1.4" strokeDasharray="4 3" opacity=".85" />
            <path d={line(S.p95)} fill="none" stroke={C.violet} strokeWidth="2" />
            <path d={line(S.p50)} fill="none" stroke={C.cyan} strokeWidth="1.6" />
          </g>
          {hi != null && <>
            <line className="cross" x1={X(hi)} x2={X(hi)} y1={pt} y2={H - pb} />
            <circle className="dotp" cx={X(hi)} cy={Y(S.p50[hi])} r="4" fill={C.cyan} stroke="#0A0A0D" strokeWidth="2" />
            <circle className="dotp" cx={X(hi)} cy={Y(S.p95[hi])} r="4" fill={C.violet} stroke="#0A0A0D" strokeWidth="2" />
            <circle className="dotp" cx={X(hi)} cy={Y(S.p99[hi])} r="4" fill={C.red} stroke="#0A0A0D" strokeWidth="2" />
          </>}
        </svg>
      </div>
    </motion.article>
  );
});

import { LayoutGroup, MotionConfig, motion } from 'framer-motion';
import { useEffect, useRef, useState } from 'react';
import { type RangeKey } from './data';
import { EventsTable, type Filter } from './EventsTable';
import { Kpis } from './Kpis';
import { LatencyChart, type LatencyHandle } from './LatencyChart';
import { Cluster, Deploys, Regions, Uptime } from './Panels';
import { ServiceMap, type ServiceMapHandle } from './ServiceMap';
import { TooltipProvider, useInterval } from './kit';
import { spring } from './motionPresets';
import './orbit.css';

const NAV: { label: string; d: string; badge?: number }[] = [
  { label: 'Overview', d: 'M3 3h7v9H3zM14 3h7v5h-7zM14 12h7v9h-7zM3 16h7v5H3z' },
  { label: 'Services', d: 'M6 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM18 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM12 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM8.5 7.5 11 15.5M15.5 7.5 13 15.5M9 6h6' },
  { label: 'Traces', d: 'M3 6h10M3 12h18M3 18h7M17 8a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM14 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z' },
  { label: 'Logs', d: 'M4 5h16M4 10h16M4 15h10M4 20h7' },
  { label: 'Deploys', d: 'M12 3v12m0 0-4-4m4 4 4-4M5 21h14' },
  { label: 'Alerts', d: 'M6 16V11a6 6 0 1 1 12 0v5l2 2H4l2-2ZM10 21h4', badge: 3 },
  { label: 'Settings', d: 'M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1' },
];
const RANGE_KEYS: RangeKey[] = ['15m', '1h', '24h', '7d'];

export interface OrbitDashboardProps {
  /** Run the hands-free tour while nobody touches the page (it pauses for 4 s after any input). Default true. */
  autoplayDemo?: boolean;
  /** Called when a sidebar item is chosen. */
  onNavigate?: (label: string) => void;
}

/** Orbit: an infra observability dashboard. Free, MIT, by qodesign.dev. */
export function OrbitDashboard(props: OrbitDashboardProps) {
  return (
    <MotionConfig reducedMotion="user">
      <TooltipProvider><Dashboard {...props} /></TooltipProvider>
    </MotionConfig>
  );
}

function Dashboard({ autoplayDemo = true, onNavigate }: OrbitDashboardProps) {
  const [range, setRange] = useState<RangeKey>('1h');
  const [live, setLive] = useState(true);
  const [page, setPage] = useState('Overview');
  const [menu, setMenu] = useState(false);
  const [filter, setFilter] = useState<Filter>('all');
  const [degraded, setDegraded] = useState<string | null>(null);
  const tick = useRef(0);
  const map = useRef<ServiceMapHandle>(null);
  const lat = useRef<LatencyHandle>(null);
  const search = useRef<HTMLInputElement>(null);
  const menuBtn = useRef<HTMLButtonElement>(null);

  // payments degrades and recovers on a loop, so the map always has something to show
  useInterval(() => {
    tick.current++;
    if (tick.current % 16 === 5) setDegraded('pay');
    if (tick.current % 16 === 13) setDegraded(null);
  }, live ? 1000 : null);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && menu) { setMenu(false); menuBtn.current?.focus(); }
      const tag = (document.activeElement?.tagName ?? '');
      if (e.key === '/' && !/INPUT|TEXTAREA/.test(tag)) { e.preventDefault(); search.current?.focus(); }
    };
    addEventListener('keydown', onKey);
    return () => removeEventListener('keydown', onKey);
  }, [menu]);

  // hands-free tour; real input wins, and the tour comes back 4 s after the last input
  useEffect(() => {
    if (!autoplayDemo) return;
    let lastInput = -1e9, stop = false;
    const mark = (e: Event) => { if (e.isTrusted) lastInput = performance.now(); };
    const markMove = (e: PointerEvent) => { if (e.pointerType === 'mouse') mark(e); };
    const evs = ['pointerdown', 'keydown', 'wheel', 'touchstart'] as const;
    evs.forEach((t) => addEventListener(t, mark, { passive: true }));
    addEventListener('pointermove', markMove, { passive: true });
    const idle = () => performance.now() - lastInput > 4000;
    const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const steps: (() => Promise<void>)[] = [
      async () => { map.current?.showNode('gw'); await wait(1800); },
      async () => { map.current?.showNode('pay'); await wait(1800); },
      async () => {
        map.current?.showNode(null);
        const n = lat.current?.points() ?? 48;
        for (let i = Math.floor(n * 0.35); i < n * 0.8 && idle() && !stop; i++) { lat.current?.hover(i); await wait(reduce ? 160 : 55); }
        await wait(900); lat.current?.hover(null);
      },
      async () => { setRange('24h'); await wait(1900); },
      async () => { setFilter('error'); await wait(1900); setFilter('all'); await wait(600); },
      async () => { setRange('1h'); await wait(1600); },
    ];
    (async () => {
      await wait(2600);
      for (let s = 0; !stop; ) {
        if (!idle() || document.hidden) { await wait(500); continue; }
        await steps[s % steps.length](); s++;
        if (!idle()) { map.current?.showNode(null); lat.current?.hover(null); }
        await wait(700);
      }
    })();
    return () => { stop = true; evs.forEach((t) => removeEventListener(t, mark)); removeEventListener('pointermove', markMove); };
  }, [autoplayDemo]);

  const onRangeKey = (e: React.KeyboardEvent) => {
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    const i = RANGE_KEYS.indexOf(range), n = RANGE_KEYS[(i + (e.key === 'ArrowRight' ? 1 : RANGE_KEYS.length - 1)) % RANGE_KEYS.length];
    setRange(n); (e.currentTarget.querySelector(`[data-r="${n}"]`) as HTMLElement | null)?.focus(); e.preventDefault();
  };

  return (
    <div className="orbit">
      <div className="app">
        <aside className={`side${menu ? ' open' : ''}`} id="orbit-side" aria-label="Main navigation">
          <div className="brand">
            <svg width="28" height="28" viewBox="0 0 28 28" aria-hidden="true"><circle cx="14" cy="14" r="5" fill="#C6FF3D" /><ellipse cx="14" cy="14" rx="12" ry="5" fill="none" stroke="#8B6CFF" strokeWidth="2" transform="rotate(-25 14 14)" /><circle cx="24" cy="9.5" r="2" fill="#F4F4F6" /></svg>
            <span>orbit</span>
          </div>
          <div className="env" role="group" aria-label="Environment"><div><b>production</b><br /><span>halcyon-cloud · 9 services</span></div><i className="dot" aria-hidden="true" /></div>
          <LayoutGroup id="orbit-nav">
            <nav className="nav">
              {NAV.map((n) => (
                <a key={n.label} href="#" aria-current={page === n.label ? 'page' : undefined}
                  onClick={(e) => { e.preventDefault(); setPage(n.label); setMenu(false); onNavigate?.(n.label); }}>
