for (let y = 6; y < 96; y += 6) for (let x = 4; x < 320; x += 6) if (BLOBS.some(([cx, cy, rx, ry]) => ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 < 1)) DOTS.push([x, y]);

