.orbit .up-card{grid-column:span 5}
.orbit .reg-card{grid-column:span 4}
.orbit .res-card{grid-column:span 3}
.orbit .dep-card{grid-column:span 4}
.orbit .ev-card{grid-column:span 8}
.orbit .map{position:relative;aspect-ratio:640/336;border-radius:var(--r-md);overflow:hidden;
  background:radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--violet) 9%,transparent),transparent 65%),
  repeating-linear-gradient(0deg,transparent 0 31px,var(--line-soft) 31px 32px),repeating-linear-gradient(90deg,transparent 0 31px,var(--line-soft) 31px 32px)}
.orbit .map svg{position:absolute;inset:0;width:100%;height:100%}
.orbit .edge{fill:none;stroke:var(--line);stroke-width:1.5;transition:stroke .3s,opacity .3s}
.orbit .edge.hot{stroke:color-mix(in srgb,var(--lime) 40%,var(--line))}
.orbit .edge.warm{stroke:color-mix(in srgb,var(--amber) 60%,var(--line))}
.orbit .map.focus .edge:not(.hl){opacity:.15}
.orbit .map.focus .node:not(.hl){opacity:.3}
.orbit .node{cursor:pointer;transition:opacity .3s}
.orbit .node .halo{fill:none;stroke-width:1.5;opacity:.5;transform-box:fill-box;transform-origin:center}
.orbit .node .core{fill:var(--panel-2);stroke-width:1.5;transition:stroke .3s}
.orbit .node .ring{fill:none;stroke-width:3;stroke-linecap:round;transform-box:fill-box;transform-origin:center;transform:rotate(-90deg);transition:stroke-dashoffset .9s var(--ease-out),stroke .3s}
.orbit .node text{font-family:var(--font-ui);font-size:11px;fill:var(--text);font-weight:600;text-anchor:middle;pointer-events:none}
.orbit .node text.code{font-family:var(--font-mono);font-size:9.5px;font-weight:600;fill:var(--text);letter-spacing:.3px}
.orbit .node text.m{font-family:var(--font-mono);font-size:9.5px;fill:var(--muted);font-weight:500}
.orbit .node:hover .core,.orbit .node:focus-visible .core{stroke:var(--text)}
/* hig-disable-next-line css/outline-none -- the focus ring is drawn on the wrapper with :focus-within (inputs) or on the node core with :focus-visible (map nodes) */
.orbit .node:focus{outline:none}
.orbit .node.degraded .halo{animation:halo 1.4s var(--ease-out) infinite}
@keyframes halo{0%{transform:scale(.9);opacity:.8}100%{transform:scale(1.6);opacity:0}}
.orbit .pkt{pointer-events:none}
.orbit .map-legend{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:10px;font-size:11px;color:var(--muted)}
.orbit .map-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px;vertical-align:middle}
.orbit .lat{position:relative;height:250px;touch-action:pan-y}
.orbit .lat svg{width:100%;height:100%;display:block;overflow:visible}
.orbit .lat .gl{stroke:var(--line-soft);stroke-width:1}
.orbit .lat .ax{fill:var(--faint);font-family:var(--font-mono);font-size:10px}
.orbit .lat .cross{stroke:var(--muted);stroke-dasharray:3 3;opacity:0;transition:opacity .15s}
.orbit .lat .dotp{opacity:0;transition:opacity .15s}
.orbit .lat.hover .cross,.orbit .lat.hover .dotp{opacity:1}
.orbit .legend{display:flex;gap:12px;font-size:12px;color:var(--muted)}
.orbit .legend i{display:inline-block;width:10px;height:3px;border-radius:2px;margin-right:6px;vertical-align:middle}
.orbit .up-row{display:grid;grid-template-columns:96px minmax(0,1fr) 62px;align-items:center;gap:10px;padding:7px 0;border-bottom:1px dashed var(--line-soft)}
.orbit .up-row:last-child{border-bottom:0}
.orbit .up-row .nm{font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.orbit .up-row .pc{text-align: end;font-family:var(--font-mono);font-size:12px;color:var(--muted)}
.orbit .bars{display:flex;gap:1px;height:26px;align-items:stretch}
.orbit .bars i{flex:1;min-width:1px;border-radius:2px;background:var(--lime);opacity:.8;transform-origin:bottom;transform:scaleY(0);animation:grow .5s var(--ease-spring) forwards;transition:opacity .15s}
.orbit .bars i.w{background:var(--amber)}
.orbit .bars i.e{background:var(--red)}
.orbit .bars i:hover{opacity:1;outline:1px solid var(--text);outline-offset:1px}
@keyframes grow{to{transform:scaleY(1)}}
.orbit .up-axis{display:flex;justify-content:space-between;margin:6px 0 0 106px;padding-right:72px;color:var(--faint);font-size:11px;font-family:var(--font-mono)}
.orbit .reg{display:flex;flex-direction:column;gap:10px}
.orbit .reg-row{display:grid;grid-template-columns:18px minmax(0,1fr) auto;align-items:center;gap:10px}
.orbit .reg-row .flag{width:10px;height:10px;border-radius:50%;justify-self:center}
.orbit .reg-row .nm{display:flex;justify-content:space-between;font-size:13px;margin-bottom:5px}
.orbit .reg-row .nm span{color:var(--muted);font-size:12px}
.orbit .track{height:6px;border-radius:6px;background:var(--line-soft);overflow:hidden}
.orbit .track i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,var(--violet),var(--cyan));transition:width .9s var(--ease-out)}
.orbit .reg-row .ms{font-size:12px;min-width:52px;text-align: end;transition:color .3s}
.orbit .globe{height:96px;margin-bottom:12px;border-radius:var(--r-md);background:var(--ink-2);border:1px solid var(--line-soft);overflow:hidden}
.orbit .globe svg{width:100%;height:100%;display:block}
.orbit .rings{display:grid;grid-template-columns:1fr;gap:12px}
.orbit .ringrow{display:flex;align-items:center;gap:14px}
.orbit .ringrow svg{width:64px;height:64px;flex:none}
.orbit .ringrow .bg{fill:none;stroke:var(--line-soft);stroke-width:7}
.orbit .ringrow .fg{fill:none;stroke-width:7;stroke-linecap:round;transform:rotate(-90deg);transform-origin:50% 50%;transition:stroke-dashoffset 1s var(--ease-out)}
.orbit .ringrow b{font-size:20px;font-weight:600}
.orbit .ringrow small{display:block;color:var(--muted);font-size:12px}
.orbit .deps{position:relative;display:flex;flex-direction:column;gap:2px}
.orbit .deps::before{content:"";position:absolute;left:13px;top:14px;bottom:14px;width:2px;background:var(--line-soft)}
.orbit .dep{position:relative;display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:12px;align-items:center;padding:8px 0}
.orbit .dep.fresh{animation:rowin .5s var(--ease-out)}
.orbit .dep .pin{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--panel);border:2px solid var(--line);z-index:1}
.orbit .dep .pin i{width:8px;height:8px;border-radius:50%}
.orbit .dep.ok .pin{border-color:color-mix(in srgb,var(--lime) 55%,var(--line))}
.orbit .dep.ok .pin i{background:var(--lime)}
.orbit .dep.fail .pin{border-color:color-mix(in srgb,var(--red) 55%,var(--line))}
.orbit .dep.fail .pin i{background:var(--red)}
.orbit .dep.run .pin{border-color:var(--violet)}
.orbit .dep.run .pin i{background:var(--violet);animation:blink 1s infinite}
@keyframes blink{50%{opacity:.25}}
.orbit .dep .t{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.orbit .dep .t code{font-family:var(--font-mono);font-size:12px;color:var(--violet);font-weight:500;margin-right:6px}
.orbit .dep .m{color:var(--muted);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.orbit .dep .prog{height:4px;border-radius:4px;background:var(--line-soft);overflow:hidden;margin-top:6px;position:relative}
.orbit .dep .prog i{position:absolute;inset:0 auto 0 0;border-radius:4px;background:linear-gradient(90deg,var(--violet),var(--lime));transition:width .6s var(--ease-out);overflow:hidden}
.orbit .dep .prog i::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.45),transparent);animation:shim 1.2s linear infinite}
@keyframes shim{from{transform:translateX(-100%)}to{transform:translateX(100%)}}
.orbit .budget{margin-top:14px;padding-top:14px;border-top:1px dashed var(--line-soft)}
.orbit .budget-h,.orbit .budget-f{display:flex;justify-content:space-between;align-items:baseline;font-size:12px;color:var(--muted)}
.orbit .budget-h b{font-size:18px;color:var(--text);font-weight:600}
.orbit .budget-f{margin-top:8px}
.orbit .budget-f b{color:var(--amber);font-weight:600}
.orbit .budget-track{position:relative;height:8px;margin-top:8px;border-radius:8px;background:var(--line-soft)}
.orbit .budget-track i{position:absolute;inset:0 auto 0 0;width:0;border-radius:8px;background:linear-gradient(90deg,var(--red),var(--amber) 30%,var(--lime));transition:width 1.4s var(--ease-out)}
.orbit .budget-track em{position:absolute;top:-3px;bottom:-3px;width:2px;border-radius:2px;background:var(--muted)}
.orbit .up-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px;padding-top:14px;border-top:1px dashed var(--line-soft)}
.orbit .up-stats small{display:block;color:var(--muted);font-size:12px}
.orbit .up-stats b{font-size:16px;font-weight:600}
.orbit .ev-tools{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px}
.orbit .filters{display:flex;gap:6px;flex-wrap:wrap}
.orbit .filters button{height:32px;min-width:44px;padding:0 12px;border-radius:99px;border:1px solid var(--line);background:var(--ink-2);color:var(--muted);font-size:12px;font-weight:600;transition:background .2s,color .2s,border-color .2s,transform .15s}
.orbit .filters button:hover{color:var(--text)}
.orbit .filters button:active{transform:scale(.96)}
.orbit .filters button[aria-pressed="true"]{background:var(--text);color:var(--ink);border-color:var(--text)}
.orbit .filters button .n{font-family:var(--font-mono);opacity:.7;margin-left:5px}
.orbit .ev-search{margin-left:auto;display:flex;align-items:center;gap:6px;height:36px;padding:0 10px;border:1px solid var(--line);border-radius:10px;background:var(--ink-2);min-width:200px;color:var(--muted)}
.orbit .ev-search:focus-within{border-color:color-mix(in srgb,var(--lime) 50%,var(--line));box-shadow:0 0 0 3px rgba(198,255,61,.22)}
/* hig-disable-next-line css/outline-none -- the focus ring is drawn on the wrapper with :focus-within (inputs) or on the node core with :focus-visible (map nodes) */
.orbit .ev-search input{border:0;background:none;outline:none;min-width:0;flex:1;font-size:13px;color:var(--text)}
.orbit .tbl-wrap{overflow:auto;max-height:388px;border:1px solid var(--line-soft);border-radius:var(--r-md);overscroll-behavior:contain}
.orbit table{width:100%;border-collapse:separate;border-spacing:0;font-size:13px;min-width:720px}
.orbit thead th{position:sticky;top:0;z-index:2;background:var(--panel-2);text-align: start;font-weight:600;color:var(--muted);font-size:12px;padding:0;border-bottom:1px solid var(--line)}
.orbit thead th button{display:flex;align-items:center;gap:6px;width:100%;height:38px;padding:0 12px;border:0;background:none;color:inherit;font-weight:600;text-align: start}
.orbit thead th button:hover{color:var(--text)}
.orbit thead th button svg{width:10px;height:10px;opacity:.3;transition:transform .25s,opacity .2s}
.orbit thead th[aria-sort="ascending"] button,.orbit thead th[aria-sort="descending"] button{color:var(--text)}
.orbit thead th[aria-sort="ascending"] button svg{opacity:1;transform:rotate(180deg)}
.orbit thead th[aria-sort="descending"] button svg{opacity:1}
.orbit tbody td{padding:9px 12px;border-bottom:1px solid var(--line-soft);white-space:nowrap}
.orbit tbody tr{transition:background .2s}
.orbit tbody tr:hover{background:color-mix(in srgb,var(--text) 4%,transparent)}
.orbit tbody tr.new{animation:flash 1.6s var(--ease-out)}
.orbit tbody tr.enter{animation:rowin .45s var(--ease-out) backwards;animation-delay:calc(var(--r,0) * 30ms)}
@keyframes flash{0%{background:color-mix(in srgb,var(--lime) 20%,transparent)}100%{background:transparent}}
@keyframes rowin{from{opacity:0;transform:translateY(6px)}}
.orbit td.mono{font-family:var(--font-mono);font-size:12px;color:var(--muted)}
.orbit td.msg{max-width:340px;overflow:hidden;text-overflow:ellipsis}
.orbit .lv{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600}
.orbit .lv::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.orbit .lv.error{color:var(--red)}
.orbit .lv.warn{color:var(--amber)}
.orbit .lv.info{color:var(--cyan)}
.orbit .empty{padding:36px 12px;text-align:center;color:var(--muted);white-space:normal}
.orbit .pager{display:flex;align-items:center;gap:10px;margin-top:10px;flex-wrap:wrap;color:var(--muted);font-size:12px}
.orbit .pager .pages{display:flex;gap:4px;margin-left:auto;align-items:center}
.orbit .pager button{min-width:32px;height:32px;padding:0 8px;border-radius:8px;border:1px solid var(--line);background:var(--ink-2);color:var(--muted);font-family:var(--font-mono);font-size:12px;transition:background .2s,color .2s,transform .15s}
.orbit .pager button:hover:not(:disabled){color:var(--text)}
.orbit .pager button:active:not(:disabled){transform:scale(.94)}
.orbit .pager button[aria-current="page"]{background:var(--lime);color:var(--ink);border-color:var(--lime)}
.orbit .pager button:disabled{opacity:.35;cursor:not-allowed}
.orbit .tip{position:fixed;left:0;top:0;z-index:50;pointer-events:none;min-width:150px;padding:10px 12px;border-radius:12px;background:color-mix(in srgb,var(--panel-2) 92%,transparent);border:1px solid var(--line);box-shadow:0 18px 40px -12px rgba(0,0,0,.7);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);font-size:12px;opacity:0;transform:translateY(4px) scale(.98);transition:opacity .15s,transform .15s}
.orbit .tip.on{opacity:1;transform:none}
.orbit .tip b{display:flex;align-items:center;gap:8px;font-size:13px;margin-bottom:6px}
.orbit .tip .r{display:flex;justify-content:space-between;gap:16px;color:var(--muted)}
.orbit .tip .r span:last-child{color:var(--text);font-family:var(--font-mono)}
.orbit .scrim{position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.5);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);opacity:0;pointer-events:none;transition:opacity .3s}
.orbit .scrim.on{opacity:1;pointer-events:auto}
@media (max-width:1180px){
.orbit .app{grid-template-columns:76px minmax(0,1fr)}
.orbit .brand span,.orbit .env,.orbit .nav a span,.orbit .nav .badge,.orbit .side-foot{display:none}
.orbit .nav a{justify-content:center;padding:0}
.orbit .nav-ind::before{left:-11px}
.orbit .kpi{grid-column:span 6}
.orbit .map-card,.orbit .ev-card,.orbit .up-card{grid-column:span 12}
.orbit .lat-card,.orbit .dep-card{grid-column:span 6}
.orbit .reg-card{grid-column:span 7}
.orbit .res-card{grid-column:span 5}

}
@media (max-width:760px){
.orbit .app{grid-template-columns:minmax(0,1fr)}
.orbit .side{position:fixed;z-index:61;left:0;top:0;bottom:0;width:272px;transform:translateX(-105%);transition:transform .4s var(--ease-out);background:var(--ink-2)}
.orbit .side.open{transform:none}
.orbit .brand span,.orbit .nav a span{display:inline}
.orbit .nav .badge{display:inline-block}
.orbit .env,.orbit .side-foot{display:flex}
.orbit .nav a{justify-content:flex-start;padding:0 12px;min-height:44px}
.orbit .nav-ind{height:44px}
.orbit .nav-ind::before{display:none}
.orbit .menu-btn{display:grid}
.orbit .main{padding:14px 14px 32px}
.orbit .crumbs h1{font-size:20px}
.orbit .top-r{width:100%;margin-left:0}
.orbit .search{order:3;width:100%;min-width:0}
.orbit .seg{flex:1}
.orbit .seg button{flex:1;min-width:0}
.orbit .grid{gap:12px}
.orbit .kpi{grid-column:span 6;padding:12px}
.orbit .kpi .val b{font-size:22px;letter-spacing:-.5px}
.orbit .kpi .spark{width:100%;height:26px}
.orbit .kpi .foot{flex-direction:column;align-items:flex-start}
.orbit .lat-card,.orbit .dep-card,.orbit .reg-card,.orbit .res-card{grid-column:span 12}
.orbit .lat{height:210px}
.orbit .map{aspect-ratio:340/476}
.orbit .up-row{grid-template-columns:72px minmax(0,1fr) 52px}
.orbit .up-axis{margin-left:82px;padding-right:62px}
.orbit .ev-search{min-width:0;width:100%;margin-left:0}

}
@media (prefers-reduced-motion:reduce){
.orbit *,.orbit *::before,.orbit *::after{animation-duration:.01ms!important;animation-delay:0s!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
.orbit .card{opacity:1;transform:none}
.orbit .bars i{transform:none}

}


/* React port: Framer Motion drives the card entrance, the nav indicator and the range pill */
.orbit .card{opacity:1;transform:none;animation:none}
.orbit .nav-ind{z-index:-1}
.orbit .nav a{isolation:isolate}
.orbit .seg button{isolation:isolate}
.orbit .seg-pill{position:absolute;border-radius:8px;background:var(--lime)}
.orbit .nav-ind,.orbit .seg-pill{transition:none}
.orbit .nav-ind{height:auto;bottom:0}
